defmodule HelloKioskBrain.Icons do
  @moduledoc "32x32 RGB565-LE icons from LovyanGFX MovingIcons (via hello_kiosk_papapa). Transparent=0x0000."

  @size 32
  def size, do: @size

  def info,
    do:
      Base.decode64!(
        ""
      )

  def alert,
    do:
      Base.decode64!(
        ""
      )

  def close,
    do:
      Base.decode64!(
        ""
      )

  def all, do: [info(), alert(), close()]
end
